{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Glimepiride tablet had an absolute bioavailability of 97% (90% CI 93-102%) versus IV in healthy male volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "PF-05150122 had an absolute oral bioavailability of 52% after a 100 µg oral dose in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Agomelatine had an absolute bioavailability below 5% at a therapeutic oral dose in humans, arguing against F >= 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable absolute-bioavailability measurements are consistently high (97%, 52%), supporting F >= 20%; lower-transferability negative records (<5%) do not outweigh them, but mixed propafenone data and qualitative low-bioavailability reports introduce uncertainty.",
  "evidence_gaps": [
    "Propafenone records conflict (90-95% vs 12-31%), making its molecule-level direction uncertain.",
    "Several low-bioavailability records are qualitative ('low') without threshold-specific numeric values and were discounted.",
    "Microdose data for PF-05150122 may not reflect therapeutic-dose bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

